document.addEventListener("DOMContentLoaded",()=>{if(!(window.location.pathname==="/"||window.location.pathname==="/index"))return;const a=document.querySelector("#aboutBtns"),o=document.querySelectorAll(".about-content");if(!a||o.length<3)return;const c=a.querySelectorAll("button[data-content]"),r={about:o[0],roles:o[1],ai:o[2]},s=t=>{Object.entries(r).forEach(([e,n])=>{n&&n.classList.toggle("display-none",e!==t)}),c.forEach(e=>{const n=e.dataset.content===t;e.dataset.active=String(n),e.disabled=n})};c.forEach(t=>{t.addEventListener("click",()=>s(t.dataset.content))});const i=a.querySelector('button[data-active="true"]')||c[0];i&&s(i.dataset.content)});
